Fail safe defaults.ejemplo:
function authorize(user, action, resource) {
  try {
    if (!user || !policyEngine.isReady()) return false; // fail-closed
    return policyEngine.allow(user, action, resource) === true;
  } catch (err) {
    auditLog.error("authz_error", err);
    return false; // nunca permitir acceso tras una excepción
  }
}

